def compute(vars):
    revolving_credit_millions = vars["v1"]
    senior_credit_facility_millions = vars["v2"] * 1000

    if senior_credit_facility_millions == 0:
        return None

    ratio_percentage = revolving_credit_millions / senior_credit_facility_millions * 100

    return {
        "value": ratio_percentage,
        "trace": {
            "revolving_credit_facility_millions": revolving_credit_millions,
            "senior_credit_facility_millions": senior_credit_facility_millions,
            "ratio_percentage": ratio_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
